#include <bits/stdc++.h>
using namespace std;
// Unsigned big integer, little-endian base 2^32 limbs; empty means zero.
typedef vector<uint32_t> Big;
static void trim(Big &a) { while (!a.empty() && a.back() == 0) a.pop_back(); }
static Big mul(const Big &a, const Big &b) {
    if (a.empty() || b.empty()) return {};
    Big r(a.size() + b.size(), 0);
    for (size_t i = 0; i < a.size(); i++) {
        uint64_t carry = 0, x = a[i];
        for (size_t j = 0; j < b.size(); j++) {
            uint64_t cur = x * b[j] + r[i + j] + carry;
            r[i + j] = (uint32_t)cur;
            carry = cur >> 32;
        }
        r[i + b.size()] = (uint32_t)carry;
    }
    trim(r);
    return r;
}
static Big mulSmall(const Big &a, uint32_t k) {
    Big r; r.reserve(a.size() + 1);
    uint64_t carry = 0;
    for (uint32_t x : a) { uint64_t cur = (uint64_t)x * k + carry; r.push_back((uint32_t)cur); carry = cur >> 32; }
    if (carry) r.push_back((uint32_t)carry);
    trim(r);
    return r;
}
static int cmp(const Big &a, const Big &b) {
    if (a.size() != b.size()) return a.size() < b.size() ? -1 : 1;
    for (size_t i = a.size(); i-- > 0;) if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
    return 0;
}
static string toString(Big a) {
    if (a.empty()) return "0";
    vector<uint32_t> parts;
    while (!a.empty()) {
        uint64_t rem = 0;
        for (size_t i = a.size(); i-- > 0;) {
            uint64_t cur = (rem << 32) | a[i];
            a[i] = (uint32_t)(cur / 1000000000u);
            rem = cur % 1000000000u;
        }
        trim(a);
        parts.push_back((uint32_t)rem);
    }
    string s = to_string(parts.back());
    char buf[16];
    for (size_t i = parts.size() - 1; i-- > 0;) { snprintf(buf, sizeof buf, "%09u", parts[i]); s += buf; }
    return s;
}
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    vector<vector<int>> g(n);
    for (int i = 0; i < n - 1; i++) { int u, v; scanf("%d %d", &u, &v); u--; v--; g[u].push_back(v); g[v].push_back(u); }
    vector<int> parent(n, -1), order = {0};
    for (size_t h = 0; h < order.size(); h++) {
        int u = order[h];
        for (int v : g[u]) if (v != parent[u]) { parent[v] = u; order.push_back(v); }
    }
    // tables[u][k]: best product of closed components when u's open component has size k.
    vector<vector<Big>> tables(n);
    for (int h = n - 1; h >= 0; h--) {
        int u = order[h];
        vector<Big> dp = {{}, {1}};
        for (int v : g[u]) {
            if (parent[v] != u) continue;
            vector<Big> &child = tables[v];
            Big best;
            for (size_t j = 1; j < child.size(); j++) { Big c = mulSmall(child[j], (uint32_t)j); if (cmp(c, best) > 0) best = c; }
            vector<Big> nxt(dp.size() + child.size() - 1);
            for (size_t k = 1; k < dp.size(); k++) {
                const Big &value = dp[k];
                Big c = mul(value, best);
                if (cmp(c, nxt[k]) > 0) nxt[k] = move(c);
                for (size_t j = 1; j < child.size(); j++) {
                    Big d = mul(value, child[j]);
                    if (cmp(d, nxt[k + j]) > 0) nxt[k + j] = move(d);
                }
            }
            dp = move(nxt);
            vector<Big>().swap(child);
        }
        tables[u] = move(dp);
    }
    Big ans;
    for (int k = 1; k < n; k++) { Big c = mulSmall(tables[0][k], (uint32_t)k); if (cmp(c, ans) > 0) ans = c; }
    printf("%s\n", toString(ans).c_str());
}

import java.math.BigInteger;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        int[] head = new int[n], nxtEdge = new int[2 * n], to = new int[2 * n];
        Arrays.fill(head, -1);
        int ec = 0;
        for (int i = 0; i < n - 1; i++) {
            int u = r.nextInt() - 1, v = r.nextInt() - 1;
            to[ec] = v; nxtEdge[ec] = head[u]; head[u] = ec++;
            to[ec] = u; nxtEdge[ec] = head[v]; head[v] = ec++;
        }
        int[] parent = new int[n], order = new int[n];
        Arrays.fill(parent, -1);
        int cnt = 1;
        for (int h = 0; h < cnt; h++) {
            int u = order[h];
            for (int e = head[u]; e != -1; e = nxtEdge[e])
                if (to[e] != parent[u]) { parent[to[e]] = u; order[cnt++] = to[e]; }
        }
        // tables[u][k]: best product of closed components when u's open component has size k.
        BigInteger[][] tables = new BigInteger[n][];
        for (int h = n - 1; h >= 0; h--) {
            int u = order[h];
            BigInteger[] dp = {BigInteger.ZERO, BigInteger.ONE};
            for (int e = head[u]; e != -1; e = nxtEdge[e]) {
                int v = to[e];
                if (parent[v] != u) continue;
                BigInteger[] child = tables[v];
                BigInteger best = BigInteger.ZERO;
                for (int j = 1; j < child.length; j++) best = best.max(child[j].multiply(BigInteger.valueOf(j)));
                BigInteger[] nxt = new BigInteger[dp.length + child.length - 1];
                Arrays.fill(nxt, BigInteger.ZERO);
                for (int k = 1; k < dp.length; k++) {
                    BigInteger value = dp[k];
                    BigInteger c = value.multiply(best);
                    if (c.compareTo(nxt[k]) > 0) nxt[k] = c;
                    for (int j = 1; j < child.length; j++) {
                        BigInteger d = value.multiply(child[j]);
                        if (d.compareTo(nxt[k + j]) > 0) nxt[k + j] = d;
                    }
                }
                dp = nxt;
                tables[v] = null;
            }
            tables[u] = dp;
        }
        BigInteger ans = BigInteger.ZERO;
        for (int k = 1; k < n; k++) ans = ans.max(tables[0][k].multiply(BigInteger.valueOf(k)));
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

