	for i := range parent {
		parent[i] = -1
	}
	order := []int{0}
	for h := 0; h < len(order); h++ {
		u := order[h]
		for _, v := range g[u] {
			if v != parent[u] {
				parent[v] = u
				order = append(order, v)
			}
		}
	}
	// tables[u][k]: best product of closed components when u's open component has size k.
	tables := make([][]*big.Int, n)
	tmp := new(big.Int)
	for h := n - 1; h >= 0; h-- {
		u := order[h]
		dp := []*big.Int{new(big.Int), big.NewInt(1)}
		for _, v := range g[u] {
			if parent[v] != u {
				continue
			}
			child := tables[v]
			best := new(big.Int)
			for j := 1; j < len(child); j++ {
				tmp.Mul(child[j], big.NewInt(int64(j)))
				if tmp.Cmp(best) > 0 {
					best.Set(tmp)
				}
			}
			nxt := make([]*big.Int, len(dp)+len(child)-1)
			for i := range nxt {
				nxt[i] = new(big.Int)
			}
			for k := 1; k < len(dp); k++ {
				value := dp[k]
				tmp.Mul(value, best)
				if tmp.Cmp(nxt[k]) > 0 {
					nxt[k].Set(tmp)
				}
				for j := 1; j < len(child); j++ {
					tmp.Mul(value, child[j])
					if tmp.Cmp(nxt[k+j]) > 0 {
						nxt[k+j].Set(tmp)
					}
				}
			}
			dp = nxt
			tables[v] = nil
		}
		tables[u] = dp
	}
	ans := new(big.Int)
	for k := 1; k < n; k++ {
		tmp.Mul(tables[0][k], big.NewInt(int64(k)))
		if tmp.Cmp(ans) > 0 {
			ans.Set(tmp)
		}
	}
	fmt.Println(ans.String())
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
